module tb_4to1_mux;

// === Global Sync Signal ===
reg llm_go_signal = 1;


   reg [3:0] a;
   reg [3:0] b;
   reg [3:0] c;
   reg [3:0] d;
   wire [3:0] out;
   reg [1:0] sel;

   reg clk;
   reg instrumented_clk;

   integer i;

   always #5 clk = !clk;
   always #20 instrumented_clk = !instrumented_clk;

   mux_4to1_case  mux0 (   .a (a),
                           .b (b),
                           .c (c),
                           .d (d),
                           .sel (sel),
                           .out (out));


   integer f;

   initial begin
       f = $fopen("output_mux_4_1_tb.txt");
       //$fwrite(f, "time,out[3],out[2],out[1],out[0]\n");
	   $fwrite(f, "time,out[0]\n");
       forever begin
           //@(posedge clk);
           #1
           //$fwrite(f, "%g,%b,%b,%b,%b\n", $time,out[3],out[2],out[1],out[0]);
		   $fwrite(f, "%g,%b\n", $time,out[0]);
       end
   end
   initial begin
      $monitor ("[%0t] sel=0x%0h a=0x%0h b=0x%0h c=0x%0h d=0x%0h out=0x%0h", $time, sel, a, b, c, d, out);

   	clk = 0;
      instrumented_clk = 0;

      sel <= 2'b00;
      a <= 4'b0001;
      b <= 4'b0010;
      c <= 4'b0100;
      d <= 4'b1000;
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB


      #100;
      sel <= 2'b01;
      #100;
      sel <= 2'b10;
      #100;
      sel <= 2'b11;

      #100;

      sel <= 2'b00;
      d <= 4'b0001;
      c <= 4'b0010;
      b <= 4'b0100;
      a <= 4'b1000;

      #100;
      sel <= 2'b01;
      #100;
      sel <= 2'b10;
      #100;
      sel <= 2'b11;


      #800 $finish;
      #850 $fclose(f);
   end
  initial begin
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

#2000000
$finish;
end


// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    // Wait for the synchronization signal to start execution
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    $display("LLM: Starting deterministic test patterns for MUX 4:1...");

    // Initialize Inputs to known state
    a = 4'b0000;
    b = 4'b0000;
    c = 4'b0000;
    d = 4'b0000;
    sel = 2'b00;
    #10;

    // ------------------------------------------------------------
    // Test Group 1: Sensitivity List & Input Propagation
    // ------------------------------------------------------------
    // Objective: Verify that changes in a, b, c, d propagate immediately
    // when selected. This targets sensitivity list deletions (e.g., removing 'a' from always @).

    // Channel A: Toggle bits while selected
    sel = 2'b00;
    a = 4'b1010; #10;
    a = 4'b0101; #10;
    a = 4'b0000; #10;

    // Channel B: Toggle bits while selected
    sel = 2'b01;
    b = 4'b1100; #10;
    b = 4'b0011; #10;
    b = 4'b0000; #10;

    // Channel C: Toggle bits while selected
    sel = 2'b10;
    c = 4'b1110; #10;
    c = 4'b0001; #10;
    c = 4'b0000; #10;

    // Channel D: Toggle bits while selected
    sel = 2'b11;
    d = 4'b0111; #10;
    d = 4'b1000; #10;
    d = 4'b0000; #10;

    // ------------------------------------------------------------
    // Test Group 2: Multiplexer Selection Logic (Unique Values)
    // ------------------------------------------------------------
    // Objective: Ensure 'sel' maps to the correct input and no aliasing occurs.
    // Targets: Operator mutations (sel+1), Case item mutations (swapping branches).

    // Assign unique powers of 2 to identify each channel clearly
    a = 4'h1; // 0001
    b = 4'h2; // 0010
    c = 4'h4; // 0100
    d = 4'h8; // 1000

    sel = 2'b00; #10; // Expect out = 1
    sel = 2'b01; #10; // Expect out = 2
    sel = 2'b10; #10; // Expect out = 4
    sel = 2'b11; #10; // Expect out = 8

    // ------------------------------------------------------------
    // Test Group 3: Bit-Level Integrity (Walking 1s)
    // ------------------------------------------------------------
    // Objective: Detect stuck-at bits or wiring errors (e.g., out[0] stuck at 0).
    // Targets: Assignment mutations, bit-select errors.

    // Using Channel A for detailed bit walk
    sel = 2'b00;
    a = 4'b0001; #10;
    a = 4'b0010; #10;
    a = 4'b0100; #10;
    a = 4'b1000; #10;
    a = 4'b1111; #10; // All 1s
    a = 4'b0000; #10; // All 0s

    // ------------------------------------------------------------
    // Test Group 4: Isolation / Crosstalk
    // ------------------------------------------------------------
    // Objective: Ensure unselected inputs do not affect the output.
    // Targets: Logic errors mixing inputs (e.g. out = a | b).

    // Select A, toggle others violently
    sel = 2'b00;
    a = 4'hA;
    b = 4'h0; c = 4'h0; d = 4'h0; #10;
    b = 4'hF; c = 4'hF; d = 4'hF; #10; // out should remain A (1010)
    b = 4'h0; c = 4'h0; d = 4'h0; #10;

    // Select D, toggle others violently
    sel = 2'b11;
    d = 4'h5;
    a = 4'h0; b = 4'h0; c = 4'h0; #10;
    a = 4'hF; b = 4'hF; c = 4'hF; #10; // out should remain 5 (0101)
    a = 4'h0; b = 4'h0; c = 4'h0; #10;

    // ------------------------------------------------------------
    // Test Group 5: Rapid Selection Switching & Latch Detection
    // ------------------------------------------------------------
    // Objective: Test transition edges of 'sel' and check for inferred latches.
    // If a case branch is deleted, the output might hold the previous value.

    a = 4'hA; b = 4'hB; c = 4'hC; d = 4'hD;

    sel = 2'b00; #10; // Load A
    sel = 2'b11; #10; // Jump to D (00 -> 11)
    sel = 2'b01; #10; // Jump to B (11 -> 01)
    sel = 2'b10; #10; // Jump to C (01 -> 10)
    sel = 2'b00; #10; // Back to A (10 -> 00)

    // 4. Cleanup / Handover
    $display("LLM: Tests Complete. Releasing control to original TB.");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (f != 0) $fclose(f);
    $finish;
end

endmodule

